import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
// The default model lives in one small file, as the runtime keeps it in settings.
export class SettingsManager {
  static create(_configDir, agentDir) { return new SettingsManager(join(agentDir, 'settings.json')); }
  constructor(file) {
    this.file = file;
    try { this.data = JSON.parse(readFileSync(file, 'utf8')); }
    catch { this.data = { defaultProvider: 'fixture', defaultModel: 'model' }; }
  }
  getDefaultProvider() { return this.data.defaultProvider; }
  getDefaultModel() { return this.data.defaultModel; }
  setDefaultModelAndProvider(provider, model) { this.data = { ...this.data, defaultProvider: provider, defaultModel: model }; }
  async flush() {
    mkdirSync(join(this.file, '..'), { recursive: true });
    writeFileSync(this.file, JSON.stringify(this.data));
  }
}
